insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Recomendações essenciais', '{"blocks":[{"type":"heading","level":2,"text":"A recomendação central"},{"type":"paragraph","text":"A Organização Mundial da Saúde e o Ministério da Saúde recomendam iniciar a amamentação na primeira hora de vida, oferecer somente leite materno nos primeiros seis meses e continuar amamentando, junto com alimentação complementar adequada, até dois anos ou mais. “Exclusivo” significa que o bebê não recebe água, chás, sucos, outros leites ou alimentos, exceto medicamentos, vitaminas, minerais ou solução de reidratação quando indicados pelo profissional da saúde."},{"type":"callout","tone":"info","title":"Mensagem-chave","text":"O leite materno já contém água suficiente, inclusive em dias quentes. Para um bebê menor de seis meses em aleitamento materno exclusivo, oferecer água ou chá pode reduzir a sucção, diminuir a produção de leite e aumentar riscos de contaminação."},{"type":"heading","level":2,"text":"Princípios que favorecem a amamentação"},{"type":"list","items":["Contato pele a pele logo após o nascimento, quando mãe e bebê estiverem clinicamente estáveis.","Alojamento conjunto e permanência próxima da mãe e do bebê.","Livre demanda: oferecer a mama quando o bebê demonstrar sinais de fome, de dia e de noite.","Evitar horários rígidos e limitar a duração da mamada.","Observar e corrigir precocemente pega e posicionamento.","Evitar bicos, chupetas e mamadeiras, especialmente no estabelecimento da amamentação, salvo indicação individualizada.","Não oferecer complemento sem avaliação clínica e sem plano de proteção da produção de leite.","Garantir apoio respeitoso, sem culpa ou coerção."]},{"type":"heading","level":2,"text":"Benefícios"},{"type":"table","columns":["Para o bebê","Para a mulher","Para a família e sociedade"],"rows":[["Proteção contra diarreias e infecções respiratórias; nutrição adequada; apoio ao desenvolvimento e menor risco futuro de excesso de peso.","Auxilia a contração uterina; associa-se a menor risco de câncer de mama e ovário e diabetes tipo 2; fortalece vínculo e autoconfiança.","Menos gastos com substitutos; menos faltas por doença; menor impacto ambiental; fortalecimento da saúde pública."]]}],"faqItems":[]}'::jsonb, '<h2>A recomendação central</h2>
<p>A Organização Mundial da Saúde e o Ministério da Saúde recomendam iniciar a amamentação na primeira hora de vida, oferecer somente leite materno nos primeiros seis meses e continuar amamentando, junto com alimentação complementar adequada, até dois anos ou mais. “Exclusivo” significa que o bebê não recebe água, chás, sucos, outros leites ou alimentos, exceto medicamentos, vitaminas, minerais ou solução de reidratação quando indicados pelo profissional da saúde.</p>
<div class="callout callout-info"><strong>Mensagem-chave</strong><p>O leite materno já contém água suficiente, inclusive em dias quentes. Para um bebê menor de seis meses em aleitamento materno exclusivo, oferecer água ou chá pode reduzir a sucção, diminuir a produção de leite e aumentar riscos de contaminação.</p></div>
<h2>Princípios que favorecem a amamentação</h2>
<ul><li>Contato pele a pele logo após o nascimento, quando mãe e bebê estiverem clinicamente estáveis.</li><li>Alojamento conjunto e permanência próxima da mãe e do bebê.</li><li>Livre demanda: oferecer a mama quando o bebê demonstrar sinais de fome, de dia e de noite.</li><li>Evitar horários rígidos e limitar a duração da mamada.</li><li>Observar e corrigir precocemente pega e posicionamento.</li><li>Evitar bicos, chupetas e mamadeiras, especialmente no estabelecimento da amamentação, salvo indicação individualizada.</li><li>Não oferecer complemento sem avaliação clínica e sem plano de proteção da produção de leite.</li><li>Garantir apoio respeitoso, sem culpa ou coerção.</li></ul>
<h2>Benefícios</h2>
<table><thead><tr><th>Para o bebê</th><th>Para a mulher</th><th>Para a família e sociedade</th></tr></thead><tbody><tr><td>Proteção contra diarreias e infecções respiratórias; nutrição adequada; apoio ao desenvolvimento e menor risco futuro de excesso de peso.</td><td>Auxilia a contração uterina; associa-se a menor risco de câncer de mama e ovário e diabetes tipo 2; fortalece vínculo e autoconfiança.</td><td>Menos gastos com substitutos; menos faltas por doença; menor impacto ambiental; fortalecimento da saúde pública.</td></tr></tbody></table>', 'published', now(), 'manual'
from sec_0;

