insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Como a lactação funciona', '{"blocks":[{"type":"heading","level":2,"text":"A mama produz leite em resposta ao esvaziamento"},{"type":"paragraph","text":"Na gestação, os hormônios preparam o tecido mamário. Após a saída da placenta, a queda da progesterona permite aumento da produção. A prolactina participa da síntese do leite; a ocitocina promove a ejeção, fazendo o leite fluir pelos ductos. Sucção frequente, efetiva e esvaziamento adequado são os principais estímulos para manter a produção."},{"type":"heading","level":2,"text":"Colostro, leite de transição e leite maduro"},{"type":"table","columns":["Fase","Características","O que orientar"],"rows":[["Colostro","Amarelado, espesso, em pequeno volume e rico em componentes de defesa.","Pequenas quantidades são esperadas; o estômago do recém-nascido é pequeno e mamadas frequentes são normais."],["Transição","Aumenta em volume e muda de aspecto nos primeiros dias.","A “descida do leite” pode vir com mamas mais cheias, calor e vazamento."],["Maduro","Composição varia ao longo do dia e da mamada.","Não é necessário trocar de mama por relógio; permita que o bebê termine espontaneamente e ofereça a outra."]]},{"type":"heading","level":2,"text":"O que realmente aumenta a produção"},{"type":"list","items":["Mais mamadas efetivas e/ou ordenhas, inclusive à noite quando necessário.","Correção da pega.","Contato pele a pele.","Tratamento de dor e dificuldades que reduzem a sucção.","Descanso possível, hidratação conforme sede e alimentação adequada.","Evitar complementos desnecessários que substituam mamadas."]}],"faqItems":[]}'::jsonb, '<h2>A mama produz leite em resposta ao esvaziamento</h2>
<p>Na gestação, os hormônios preparam o tecido mamário. Após a saída da placenta, a queda da progesterona permite aumento da produção. A prolactina participa da síntese do leite; a ocitocina promove a ejeção, fazendo o leite fluir pelos ductos. Sucção frequente, efetiva e esvaziamento adequado são os principais estímulos para manter a produção.</p>
<h2>Colostro, leite de transição e leite maduro</h2>
<table><thead><tr><th>Fase</th><th>Características</th><th>O que orientar</th></tr></thead><tbody><tr><td>Colostro</td><td>Amarelado, espesso, em pequeno volume e rico em componentes de defesa.</td><td>Pequenas quantidades são esperadas; o estômago do recém-nascido é pequeno e mamadas frequentes são normais.</td></tr><tr><td>Transição</td><td>Aumenta em volume e muda de aspecto nos primeiros dias.</td><td>A “descida do leite” pode vir com mamas mais cheias, calor e vazamento.</td></tr><tr><td>Maduro</td><td>Composição varia ao longo do dia e da mamada.</td><td>Não é necessário trocar de mama por relógio; permita que o bebê termine espontaneamente e ofereça a outra.</td></tr></tbody></table>
<h2>O que realmente aumenta a produção</h2>
<ul><li>Mais mamadas efetivas e/ou ordenhas, inclusive à noite quando necessário.</li><li>Correção da pega.</li><li>Contato pele a pele.</li><li>Tratamento de dor e dificuldades que reduzem a sucção.</li><li>Descanso possível, hidratação conforme sede e alimentação adequada.</li><li>Evitar complementos desnecessários que substituam mamadas.</li></ul>', 'published', now(), 'manual'
from sec_1;

