insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Primeiras horas e primeiros dias', '{"blocks":[{"type":"heading","level":2,"text":"Primeira hora de vida"},{"type":"paragraph","text":"Quando não houver contraindicação clínica, o contato pele a pele ininterrupto ajuda a estabilizar temperatura, respiração e glicemia, favorece o vínculo e aumenta a chance de início precoce da amamentação. Procedimentos de rotina podem ser organizados para não separar a dupla desnecessariamente."},{"type":"heading","level":2,"text":"Comportamentos normais"},{"type":"list","items":["Mamadas muito frequentes, inclusive em “blocos” no fim do dia.","Sono variável e necessidade de acordar recém-nascido em situações específicas.","Pouco colostro visível, mas suficiente quando a transferência está adequada.","Fezes mudando de mecônio escuro para tons esverdeados e depois amarelados.","Perda de peso nos primeiros dias, que deve ser acompanhada clinicamente."]},{"type":"heading","level":2,"text":"Quando acordar o bebê"},{"type":"paragraph","text":"Recém-nascidos prematuros, pequenos, com icterícia, baixo ganho ponderal, sonolência excessiva ou outras condições podem precisar de oferta programada e avaliação de mamadas. A orientação deve ser individualizada. Em geral, enquanto a amamentação não está bem estabelecida, não se deve permitir longos intervalos sem avaliar sinais clínicos e evolução do peso."}],"faqItems":[]}'::jsonb, '<h2>Primeira hora de vida</h2>
<p>Quando não houver contraindicação clínica, o contato pele a pele ininterrupto ajuda a estabilizar temperatura, respiração e glicemia, favorece o vínculo e aumenta a chance de início precoce da amamentação. Procedimentos de rotina podem ser organizados para não separar a dupla desnecessariamente.</p>
<h2>Comportamentos normais</h2>
<ul><li>Mamadas muito frequentes, inclusive em “blocos” no fim do dia.</li><li>Sono variável e necessidade de acordar recém-nascido em situações específicas.</li><li>Pouco colostro visível, mas suficiente quando a transferência está adequada.</li><li>Fezes mudando de mecônio escuro para tons esverdeados e depois amarelados.</li><li>Perda de peso nos primeiros dias, que deve ser acompanhada clinicamente.</li></ul>
<h2>Quando acordar o bebê</h2>
<p>Recém-nascidos prematuros, pequenos, com icterícia, baixo ganho ponderal, sonolência excessiva ou outras condições podem precisar de oferta programada e avaliação de mamadas. A orientação deve ser individualizada. Em geral, enquanto a amamentação não está bem estabelecida, não se deve permitir longos intervalos sem avaliar sinais clínicos e evolução do peso.</p>', 'published', now(), 'manual'
from sec_2;

with sec_3 as (
  insert into sections (slug, order_index, icon, content_kind)
  values ('pega-e-posicionamento', 3, 'Baby', 'article')
  returning id
)
insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Pega e posicionamento', '{"blocks":[{"type":"heading","level":2,"text":"Posicionamento adequado"},{"type":"list","items":["Mãe confortável, costas e braços apoiados.","Bebê de frente para a mama, barriga voltada para o corpo da mãe.","Cabeça e tronco alinhados; pescoço sem torção.","Corpo do bebê próximo e bem sustentado.","Nariz na altura do mamilo antes de iniciar a pega."]},{"type":"heading","level":2,"text":"Sinais de boa pega"},{"type":"list","items":["Boca bem aberta.","Queixo tocando a mama.","Lábios virados para fora.","Mais aréola visível acima da boca do que abaixo, quando a anatomia permite observar.","Bochechas arredondadas, sem covinhas.","Sucções lentas e profundas, com pausas e deglutição perceptível.","Ausência de dor persistente; pode haver sensibilidade inicial breve, mas não dor intensa durante toda a mamada."]},{"type":"heading","level":2,"text":"Como ajudar o bebê a pegar"},{"type":"list","items":["Aproxime o bebê da mama, em vez de levar a mama até ele.","Toque o lábio superior com o mamilo e aguarde a boca abrir bem.","Direcione o mamilo para o palato e aproxime rapidamente o corpo do bebê.","Observe conforto e deglutição.","Se doer, introduza delicadamente o dedo mínimo no canto da boca para quebrar o vácuo e tente novamente."]},{"type":"heading","level":2,"text":"Posições úteis"},{"type":"table","columns":["Posição","Pode ajudar quando..."],"rows":[["Tradicional","Mãe e bebê estão confortáveis e a pega já está se estabelecendo."],["Cruzada","É necessário maior controle da cabeça para corrigir a pega."],["Invertida ou “bola de futebol”","Após cesárea, em mamas grandes, gêmeos ou necessidade de visualizar melhor a pega."],["Deitada de lado","Mãe precisa descansar; requer ambiente seguro e atenção ao risco de adormecer."],["Cavalinho","Bebês com refluxo, hipotonia ou dificuldade de coordenação, sob orientação."]]},{"type":"callout","tone":"warning","title":"Dor não deve ser normalizada","text":"Fissuras, sangramento, deformação do mamilo ao final da mamada ou dor que não melhora após ajuste indicam necessidade de avaliação."}],"faqItems":[]}'::jsonb, '<h2>Posicionamento adequado</h2>
<ul><li>Mãe confortável, costas e braços apoiados.</li><li>Bebê de frente para a mama, barriga voltada para o corpo da mãe.</li><li>Cabeça e tronco alinhados; pescoço sem torção.</li><li>Corpo do bebê próximo e bem sustentado.</li><li>Nariz na altura do mamilo antes de iniciar a pega.</li></ul>
<h2>Sinais de boa pega</h2>
<ul><li>Boca bem aberta.</li><li>Queixo tocando a mama.</li><li>Lábios virados para fora.</li><li>Mais aréola visível acima da boca do que abaixo, quando a anatomia permite observar.</li><li>Bochechas arredondadas, sem covinhas.</li><li>Sucções lentas e profundas, com pausas e deglutição perceptível.</li><li>Ausência de dor persistente; pode haver sensibilidade inicial breve, mas não dor intensa durante toda a mamada.</li></ul>
<h2>Como ajudar o bebê a pegar</h2>
<ul><li>Aproxime o bebê da mama, em vez de levar a mama até ele.</li><li>Toque o lábio superior com o mamilo e aguarde a boca abrir bem.</li><li>Direcione o mamilo para o palato e aproxime rapidamente o corpo do bebê.</li><li>Observe conforto e deglutição.</li><li>Se doer, introduza delicadamente o dedo mínimo no canto da boca para quebrar o vácuo e tente novamente.</li></ul>
<h2>Posições úteis</h2>
<table><thead><tr><th>Posição</th><th>Pode ajudar quando...</th></tr></thead><tbody><tr><td>Tradicional</td><td>Mãe e bebê estão confortáveis e a pega já está se estabelecendo.</td></tr><tr><td>Cruzada</td><td>É necessário maior controle da cabeça para corrigir a pega.</td></tr><tr><td>Invertida ou “bola de futebol”</td><td>Após cesárea, em mamas grandes, gêmeos ou necessidade de visualizar melhor a pega.</td></tr><tr><td>Deitada de lado</td><td>Mãe precisa descansar; requer ambiente seguro e atenção ao risco de adormecer.</td></tr><tr><td>Cavalinho</td><td>Bebês com refluxo, hipotonia ou dificuldade de coordenação, sob orientação.</td></tr></tbody></table>
<div class="callout callout-warning"><strong>Dor não deve ser normalizada</strong><p>Fissuras, sangramento, deformação do mamilo ao final da mamada ou dor que não melhora após ajuste indicam necessidade de avaliação.</p></div>', 'published', now(), 'manual'
from sec_3;

