insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Como saber se o bebê mama o suficiente', '{"blocks":[{"type":"heading","level":2,"text":"Sinais favoráveis"},{"type":"list","items":["Mamada com sucção profunda e deglutição.","Bebê relaxa mãos e corpo após a mamada.","Eliminação de urina em quantidade progressiva nos primeiros dias.","Fezes com transição esperada.","Ganho de peso acompanhado na curva de crescimento.","Mamas mais macias após mamadas."]},{"type":"heading","level":2,"text":"Fraldas e evacuações"},{"type":"paragraph","text":"A contagem de fraldas é apenas um dos indicadores. A partir da subida do leite, costuma-se esperar várias fraldas bem molhadas ao dia; a OMS usa como referência pelo menos seis fraldas descartáveis molhadas em 24 horas, junto com crescimento adequado e fezes compatíveis. A avaliação do peso, do estado geral e da mamada é indispensável."},{"type":"heading","level":2,"text":"Peso"},{"type":"paragraph","text":"A interpretação deve considerar idade gestacional, peso ao nascer, perda inicial, recuperação, técnica de pesagem e curva da OMS. Não se deve concluir “leite fraco” por um único peso. Perda excessiva, ausência de recuperação esperada ou ganho insuficiente exigem avaliação da mamada, condições clínicas, frequência de oferta e, quando necessário, plano de suplementação temporária com proteção da lactação."}],"faqItems":[]}'::jsonb, '<h2>Sinais favoráveis</h2>
<ul><li>Mamada com sucção profunda e deglutição.</li><li>Bebê relaxa mãos e corpo após a mamada.</li><li>Eliminação de urina em quantidade progressiva nos primeiros dias.</li><li>Fezes com transição esperada.</li><li>Ganho de peso acompanhado na curva de crescimento.</li><li>Mamas mais macias após mamadas.</li></ul>
<h2>Fraldas e evacuações</h2>
<p>A contagem de fraldas é apenas um dos indicadores. A partir da subida do leite, costuma-se esperar várias fraldas bem molhadas ao dia; a OMS usa como referência pelo menos seis fraldas descartáveis molhadas em 24 horas, junto com crescimento adequado e fezes compatíveis. A avaliação do peso, do estado geral e da mamada é indispensável.</p>
<h2>Peso</h2>
<p>A interpretação deve considerar idade gestacional, peso ao nascer, perda inicial, recuperação, técnica de pesagem e curva da OMS. Não se deve concluir “leite fraco” por um único peso. Perda excessiva, ausência de recuperação esperada ou ganho insuficiente exigem avaliação da mamada, condições clínicas, frequência de oferta e, quando necessário, plano de suplementação temporária com proteção da lactação.</p>', 'published', now(), 'manual'
from sec_4;

