insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Dificuldades frequentes e manejo', '{"blocks":[{"type":"heading","level":2,"text":"Ingurgitamento mamário"},{"type":"paragraph","text":"A mama fica muito cheia, endurecida e dolorosa; a aréola pode ficar tensa, dificultando a pega. Ocorre quando há produção maior que a retirada, mamadas ineficazes ou intervalos longos."},{"type":"list","items":["Amamentar com frequência e corrigir a pega.","Antes da mamada, fazer massagem suave e pequena ordenha para amolecer a aréola.","Após a mamada, aplicar frio por curto período para conforto, protegido por tecido.","Usar sutiã confortável, sem compressão.","Evitar massagens vigorosas, calor prolongado e esvaziamento excessivo sem necessidade, pois podem aumentar edema e produção."]},{"type":"heading","level":2,"text":"Fissuras e trauma mamilar"},{"type":"paragraph","text":"A causa mais comum é pega inadequada. Também podem contribuir retirada incorreta do bebê, bombas mal ajustadas, dermatites, infecções e alterações orais."},{"type":"list","items":["Corrigir a causa.","Manter a região limpa e seca; lavar as mamas apenas durante o banho, sem sabonetes agressivos no mamilo.","Evitar álcool, pomadas caseiras, cascas de alimentos e exposição solar como tratamento.","Avaliar sinais de infecção e necessidade de tratamento específico."]},{"type":"heading","level":2,"text":"Ductos inflamados e mastite"},{"type":"paragraph","text":"Dor localizada, área avermelhada, edema e mal-estar podem fazer parte do espectro inflamatório da mastite. Febre persistente, piora clínica ou ausência de melhora exigem avaliação médica. Em geral, manter a amamentação é seguro e ajuda a resolver a estase; interrupção abrupta pode piorar."},{"type":"list","items":["Repouso, hidratação, analgesia compatível com lactação e frio local podem ajudar.","Evitar apertar, “desmanchar caroço” com força ou usar vibração agressiva.","Antibiótico só quando indicado.","Suspeitar de abscesso se houver massa flutuante, piora ou persistência; pode necessitar imagem e drenagem."]},{"type":"heading","level":2,"text":"Candidíase: cuidado com diagnósticos excessivos"},{"type":"paragraph","text":"Dor em queimação e mamilo brilhante são frequentemente atribuídos à candidíase, mas podem ter outras causas, como trauma, vasoespasmo ou dermatite. O diagnóstico deve ser clínico e o tratamento, direcionado. Não usar antifúngicos repetidamente sem reavaliação."},{"type":"heading","level":2,"text":"Baixa produção percebida ou real"},{"type":"paragraph","text":"Mamas mais macias, ausência de vazamento e mamadas frequentes não provam baixa produção. A avaliação deve se basear em transferência, diurese, fezes, peso e estado clínico."},{"type":"heading","level":2,"text":"Reflexo de ejeção forte e excesso de leite"},{"type":"list","items":["Posição reclinada pode reduzir o fluxo.","Permitir pausas e arroto.","Evitar ordenhar grandes volumes apenas para “esvaziar”.","Avaliar ganho de peso, desconforto, engasgos e fezes."]},{"type":"callout","tone":"warning","title":"Atenção","text":"Chás, cerveja preta, canjica e produtos “lactagogos” não substituem avaliação da mamada. Alguns podem ser prejudiciais ou interagir com medicamentos."},{"type":"callout","tone":"danger","title":"Sinais de alerta no recém-nascido","text":"Dificuldade para acordar, recusa persistente da mama, menos urina, boca seca, choro fraco, febre ou temperatura baixa, icterícia intensa, respiração rápida ou com esforço, coloração azulada, vômitos verdes ou perda de peso importante exigem avaliação imediata."}],"faqItems":[]}'::jsonb, '<h2>Ingurgitamento mamário</h2>
<p>A mama fica muito cheia, endurecida e dolorosa; a aréola pode ficar tensa, dificultando a pega. Ocorre quando há produção maior que a retirada, mamadas ineficazes ou intervalos longos.</p>
<ul><li>Amamentar com frequência e corrigir a pega.</li><li>Antes da mamada, fazer massagem suave e pequena ordenha para amolecer a aréola.</li><li>Após a mamada, aplicar frio por curto período para conforto, protegido por tecido.</li><li>Usar sutiã confortável, sem compressão.</li><li>Evitar massagens vigorosas, calor prolongado e esvaziamento excessivo sem necessidade, pois podem aumentar edema e produção.</li></ul>
<h2>Fissuras e trauma mamilar</h2>
<p>A causa mais comum é pega inadequada. Também podem contribuir retirada incorreta do bebê, bombas mal ajustadas, dermatites, infecções e alterações orais.</p>
<ul><li>Corrigir a causa.</li><li>Manter a região limpa e seca; lavar as mamas apenas durante o banho, sem sabonetes agressivos no mamilo.</li><li>Evitar álcool, pomadas caseiras, cascas de alimentos e exposição solar como tratamento.</li><li>Avaliar sinais de infecção e necessidade de tratamento específico.</li></ul>
<h2>Ductos inflamados e mastite</h2>
<p>Dor localizada, área avermelhada, edema e mal-estar podem fazer parte do espectro inflamatório da mastite. Febre persistente, piora clínica ou ausência de melhora exigem avaliação médica. Em geral, manter a amamentação é seguro e ajuda a resolver a estase; interrupção abrupta pode piorar.</p>
<ul><li>Repouso, hidratação, analgesia compatível com lactação e frio local podem ajudar.</li><li>Evitar apertar, “desmanchar caroço” com força ou usar vibração agressiva.</li><li>Antibiótico só quando indicado.</li><li>Suspeitar de abscesso se houver massa flutuante, piora ou persistência; pode necessitar imagem e drenagem.</li></ul>
<h2>Candidíase: cuidado com diagnósticos excessivos</h2>
<p>Dor em queimação e mamilo brilhante são frequentemente atribuídos à candidíase, mas podem ter outras causas, como trauma, vasoespasmo ou dermatite. O diagnóstico deve ser clínico e o tratamento, direcionado. Não usar antifúngicos repetidamente sem reavaliação.</p>
<h2>Baixa produção percebida ou real</h2>
<p>Mamas mais macias, ausência de vazamento e mamadas frequentes não provam baixa produção. A avaliação deve se basear em transferência, diurese, fezes, peso e estado clínico.</p>
<h2>Reflexo de ejeção forte e excesso de leite</h2>
<ul><li>Posição reclinada pode reduzir o fluxo.</li><li>Permitir pausas e arroto.</li><li>Evitar ordenhar grandes volumes apenas para “esvaziar”.</li><li>Avaliar ganho de peso, desconforto, engasgos e fezes.</li></ul>
<div class="callout callout-warning"><strong>Atenção</strong><p>Chás, cerveja preta, canjica e produtos “lactagogos” não substituem avaliação da mamada. Alguns podem ser prejudiciais ou interagir com medicamentos.</p></div>
<div class="callout callout-danger"><strong>Sinais de alerta no recém-nascido</strong><p>Dificuldade para acordar, recusa persistente da mama, menos urina, boca seca, choro fraco, febre ou temperatura baixa, icterícia intensa, respiração rápida ou com esforço, coloração azulada, vômitos verdes ou perda de peso importante exigem avaliação imediata.</p></div>', 'published', now(), 'manual'
from sec_5;

