insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Ordenha, conservação e oferta', '{"blocks":[{"type":"heading","level":2,"text":"Quando ordenhar"},{"type":"list","items":["Para aliviar aréola tensa antes da pega.","Quando mãe e bebê estão separados.","Para estimular produção em prematuros ou sucção ineficaz.","Para formar estoque antes do retorno ao trabalho.","Para doação ao Banco de Leite Humano."]},{"type":"heading","level":2,"text":"Ordenha manual"},{"type":"list","items":["Lave as mãos e escolha local limpo e tranquilo.","Massageie suavemente a mama em movimentos circulares.","Posicione polegar acima e indicador abaixo da aréola, formando um “C”.","Empurre os dedos para trás, em direção ao tórax, e comprima ritmicamente sem deslizar sobre a pele.","Alterne os pontos ao redor da aréola e troque de mama.","Colete em recipiente adequado e identificado."]},{"type":"heading","level":2,"text":"Bomba"},{"type":"paragraph","text":"A bomba não deve causar dor. O tamanho do funil precisa permitir movimento do mamilo sem atrito excessivo. Comece com sucção baixa e aumente até o máximo confortável. Higienize as partes conforme instruções do fabricante e recomendações sanitárias."},{"type":"heading","level":2,"text":"Conservação: diferencie uso doméstico e doação"},{"type":"callout","tone":"info","title":"Importante","text":"As regras do Banco de Leite para doação podem ser mais restritivas. O Ministério da Saúde orienta que o leite destinado à doação fique congelado por até 10 dias antes de ser entregue ao Banco de Leite. Para consumo do próprio bebê, siga o protocolo do serviço que acompanha a família e as condições de armazenamento."},{"type":"table","columns":["Etapa","Boas práticas"],"rows":[["Recipiente","Vidro de boca larga com tampa plástica, esterilizado conforme orientação do Banco de Leite, ou recipiente próprio para leite humano."],["Identificação","Nome, data e hora da coleta; quando aplicável, idade gestacional ou identificação do bebê."],["Resfriamento","Guardar imediatamente no local indicado; evitar porta da geladeira."],["Descongelamento","Na geladeira ou em banho-maria com água morna, sem ferver."],["Aquecimento","Nunca usar micro-ondas: pode criar pontos quentes e alterar componentes."],["Sobras","Não recongelar leite descongelado; descarte sobra que teve contato com a saliva conforme orientação do serviço."]]},{"type":"heading","level":2,"text":"Como oferecer"},{"type":"paragraph","text":"Copo pequeno, colher ou dispositivo indicado podem ser usados. Mamadeira não é obrigatória e pode interferir na dinâmica oral em algumas crianças. A escolha deve considerar idade, habilidade, segurança e orientação profissional. Nunca despeje o leite na boca; permita que o bebê lamba e sorva, em posição semissentada."}],"faqItems":[]}'::jsonb, '<h2>Quando ordenhar</h2>
<ul><li>Para aliviar aréola tensa antes da pega.</li><li>Quando mãe e bebê estão separados.</li><li>Para estimular produção em prematuros ou sucção ineficaz.</li><li>Para formar estoque antes do retorno ao trabalho.</li><li>Para doação ao Banco de Leite Humano.</li></ul>
<h2>Ordenha manual</h2>
<ul><li>Lave as mãos e escolha local limpo e tranquilo.</li><li>Massageie suavemente a mama em movimentos circulares.</li><li>Posicione polegar acima e indicador abaixo da aréola, formando um “C”.</li><li>Empurre os dedos para trás, em direção ao tórax, e comprima ritmicamente sem deslizar sobre a pele.</li><li>Alterne os pontos ao redor da aréola e troque de mama.</li><li>Colete em recipiente adequado e identificado.</li></ul>
<h2>Bomba</h2>
<p>A bomba não deve causar dor. O tamanho do funil precisa permitir movimento do mamilo sem atrito excessivo. Comece com sucção baixa e aumente até o máximo confortável. Higienize as partes conforme instruções do fabricante e recomendações sanitárias.</p>
<h2>Conservação: diferencie uso doméstico e doação</h2>
<div class="callout callout-info"><strong>Importante</strong><p>As regras do Banco de Leite para doação podem ser mais restritivas. O Ministério da Saúde orienta que o leite destinado à doação fique congelado por até 10 dias antes de ser entregue ao Banco de Leite. Para consumo do próprio bebê, siga o protocolo do serviço que acompanha a família e as condições de armazenamento.</p></div>
<table><thead><tr><th>Etapa</th><th>Boas práticas</th></tr></thead><tbody><tr><td>Recipiente</td><td>Vidro de boca larga com tampa plástica, esterilizado conforme orientação do Banco de Leite, ou recipiente próprio para leite humano.</td></tr><tr><td>Identificação</td><td>Nome, data e hora da coleta; quando aplicável, idade gestacional ou identificação do bebê.</td></tr><tr><td>Resfriamento</td><td>Guardar imediatamente no local indicado; evitar porta da geladeira.</td></tr><tr><td>Descongelamento</td><td>Na geladeira ou em banho-maria com água morna, sem ferver.</td></tr><tr><td>Aquecimento</td><td>Nunca usar micro-ondas: pode criar pontos quentes e alterar componentes.</td></tr><tr><td>Sobras</td><td>Não recongelar leite descongelado; descarte sobra que teve contato com a saliva conforme orientação do serviço.</td></tr></tbody></table>
<h2>Como oferecer</h2>
<p>Copo pequeno, colher ou dispositivo indicado podem ser usados. Mamadeira não é obrigatória e pode interferir na dinâmica oral em algumas crianças. A escolha deve considerar idade, habilidade, segurança e orientação profissional. Nunca despeje o leite na boca; permita que o bebê lamba e sorva, em posição semissentada.</p>', 'published', now(), 'manual'
from sec_6;

