insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Alimentação, medicamentos e hábitos maternos', '{"blocks":[{"type":"heading","level":2,"text":"Alimentação da mulher"},{"type":"paragraph","text":"Não existe dieta universal da lactante. A maioria das mulheres pode manter alimentação variada, baseada em alimentos in natura e minimamente processados. Beba água conforme sede. Restrições alimentares sem indicação podem causar deficiência, culpa e abandono precoce da amamentação."},{"type":"heading","level":2,"text":"Cafeína, álcool e tabaco"},{"type":"list","items":["Cafeína: moderar e observar irritabilidade ou alteração do sono do bebê; considerar café, chás, energéticos e chocolate.","Álcool: a opção mais segura é não consumir. Estratégias baseadas em intervalo devem ser discutidas com profissional, pois “ordenhar e descartar” não acelera a eliminação do álcool.","Tabaco e vape: evitar. Se a mulher não consegue parar imediatamente, deve receber apoio para cessação e reduzir exposição passiva; não fumar perto do bebê nem em ambientes fechados.","Drogas ilícitas: podem contraindicar temporariamente a amamentação e exigem avaliação urgente e suporte sem julgamento."]},{"type":"heading","level":2,"text":"Medicamentos"},{"type":"paragraph","text":"Grande parte dos medicamentos é compatível com a amamentação. Suspender o leite sem necessidade pode trazer mais risco do que manter. A decisão deve considerar idade e saúde do bebê, dose, via, duração, transferência para o leite e alternativas. Consulte fontes especializadas e profissional habilitado."},{"type":"callout","tone":"danger","title":"Nunca faça por conta própria","text":"Não interrompa medicação essencial nem a amamentação sem orientação. Fitoterápicos, “naturais” e suplementos também podem causar efeitos e interações."}],"faqItems":[]}'::jsonb, '<h2>Alimentação da mulher</h2>
<p>Não existe dieta universal da lactante. A maioria das mulheres pode manter alimentação variada, baseada em alimentos in natura e minimamente processados. Beba água conforme sede. Restrições alimentares sem indicação podem causar deficiência, culpa e abandono precoce da amamentação.</p>
<h2>Cafeína, álcool e tabaco</h2>
<ul><li>Cafeína: moderar e observar irritabilidade ou alteração do sono do bebê; considerar café, chás, energéticos e chocolate.</li><li>Álcool: a opção mais segura é não consumir. Estratégias baseadas em intervalo devem ser discutidas com profissional, pois “ordenhar e descartar” não acelera a eliminação do álcool.</li><li>Tabaco e vape: evitar. Se a mulher não consegue parar imediatamente, deve receber apoio para cessação e reduzir exposição passiva; não fumar perto do bebê nem em ambientes fechados.</li><li>Drogas ilícitas: podem contraindicar temporariamente a amamentação e exigem avaliação urgente e suporte sem julgamento.</li></ul>
<h2>Medicamentos</h2>
<p>Grande parte dos medicamentos é compatível com a amamentação. Suspender o leite sem necessidade pode trazer mais risco do que manter. A decisão deve considerar idade e saúde do bebê, dose, via, duração, transferência para o leite e alternativas. Consulte fontes especializadas e profissional habilitado.</p>
<div class="callout callout-danger"><strong>Nunca faça por conta própria</strong><p>Não interrompa medicação essencial nem a amamentação sem orientação. Fitoterápicos, “naturais” e suplementos também podem causar efeitos e interações.</p></div>', 'published', now(), 'manual'
from sec_7;

