insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Situações especiais e contraindicações', '{"blocks":[{"type":"heading","level":2,"text":"Poucas situações contraindicam totalmente"},{"type":"paragraph","text":"No Brasil, mães vivendo com HIV e mães com HTLV-1 ou HTLV-2 não devem amamentar, devido ao risco de transmissão. O SUS deve garantir orientação, inibição da lactação quando indicada e fórmula infantil. Aleitamento cruzado - outra mulher amamentar o bebê - não é recomendado devido ao risco de transmissão de infecções."},{"type":"heading","level":2,"text":"Situações que exigem avaliação individual"},{"type":"table","columns":["Condição","Orientação geral"],"rows":[["Hepatite B","Em geral, amamentação permitida com imunoprofilaxia adequada do recém-nascido."],["Hepatite C","Em geral, permitida; avaliar sangramento mamilar e situações específicas."],["Tuberculose","Frequentemente é possível manter leite materno com medidas de controle e tratamento; conduta depende de contagiosidade."],["Herpes","Não oferecer a mama com lesão ativa; proteger lesões em outras áreas e manter higiene."],["COVID-19/influenza","Em geral, manter amamentação com higiene das mãos e medidas respiratórias indicadas."],["Uso de radiofármacos ou medicamentos específicos","Pode exigir pausa temporária ou contraindicação; buscar fonte especializada."],["Galactosemia clássica no bebê","Contraindicação ao leite humano."]]},{"type":"callout","tone":"warning","title":"Segurança","text":"Esta tabela é resumida. A conduta depende do diagnóstico, tratamento e condição do bebê. Procure avaliação especializada."},{"type":"callout","tone":"info","title":"Autonomia e acolhimento","text":"Promover a amamentação não significa obrigar. Mulheres que não podem ou não desejam amamentar também merecem orientação segura, acesso à alimentação apropriada e cuidado sem julgamento."}],"faqItems":[]}'::jsonb, '<h2>Poucas situações contraindicam totalmente</h2>
<p>No Brasil, mães vivendo com HIV e mães com HTLV-1 ou HTLV-2 não devem amamentar, devido ao risco de transmissão. O SUS deve garantir orientação, inibição da lactação quando indicada e fórmula infantil. Aleitamento cruzado - outra mulher amamentar o bebê - não é recomendado devido ao risco de transmissão de infecções.</p>
<h2>Situações que exigem avaliação individual</h2>
<table><thead><tr><th>Condição</th><th>Orientação geral</th></tr></thead><tbody><tr><td>Hepatite B</td><td>Em geral, amamentação permitida com imunoprofilaxia adequada do recém-nascido.</td></tr><tr><td>Hepatite C</td><td>Em geral, permitida; avaliar sangramento mamilar e situações específicas.</td></tr><tr><td>Tuberculose</td><td>Frequentemente é possível manter leite materno com medidas de controle e tratamento; conduta depende de contagiosidade.</td></tr><tr><td>Herpes</td><td>Não oferecer a mama com lesão ativa; proteger lesões em outras áreas e manter higiene.</td></tr><tr><td>COVID-19/influenza</td><td>Em geral, manter amamentação com higiene das mãos e medidas respiratórias indicadas.</td></tr><tr><td>Uso de radiofármacos ou medicamentos específicos</td><td>Pode exigir pausa temporária ou contraindicação; buscar fonte especializada.</td></tr><tr><td>Galactosemia clássica no bebê</td><td>Contraindicação ao leite humano.</td></tr></tbody></table>
<div class="callout callout-warning"><strong>Segurança</strong><p>Esta tabela é resumida. A conduta depende do diagnóstico, tratamento e condição do bebê. Procure avaliação especializada.</p></div>
<div class="callout callout-info"><strong>Autonomia e acolhimento</strong><p>Promover a amamentação não significa obrigar. Mulheres que não podem ou não desejam amamentar também merecem orientação segura, acesso à alimentação apropriada e cuidado sem julgamento.</p></div>', 'published', now(), 'manual'
from sec_8;

