insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Prematuridade, internação e Método Canguru', '{"blocks":[{"type":"heading","level":2,"text":"Leite humano é especialmente importante"},{"type":"paragraph","text":"Prematuros e recém-nascidos de baixo peso se beneficiam do leite da própria mãe e, quando este não está disponível, do leite humano pasteurizado conforme indicação. Muitas vezes a sucção direta ainda não é possível, então a produção precisa ser iniciada e mantida por ordenha."},{"type":"list","items":["Iniciar estímulo o mais precocemente possível após o parto, conforme condição materna.","Ordenhar com frequência semelhante às mamadas de um recém-nascido.","Realizar contato pele a pele e Método Canguru quando liberado.","Registrar volumes sem transformar a ordenha em fonte de culpa.","Receber apoio para transição de sonda/copo para o peito, conforme maturidade."]},{"type":"heading","level":2,"text":"Licença-maternidade em internação prolongada"},{"type":"paragraph","text":"A Lei nº 15.222/2025 passou a permitir, em determinadas internações relacionadas ao parto que ultrapassem duas semanas, extensão da licença-maternidade por até 120 dias após a alta da mãe e do recém-nascido, descontado o período anterior ao parto, conforme requisitos legais."}],"faqItems":[]}'::jsonb, '<h2>Leite humano é especialmente importante</h2>
<p>Prematuros e recém-nascidos de baixo peso se beneficiam do leite da própria mãe e, quando este não está disponível, do leite humano pasteurizado conforme indicação. Muitas vezes a sucção direta ainda não é possível, então a produção precisa ser iniciada e mantida por ordenha.</p>
<ul><li>Iniciar estímulo o mais precocemente possível após o parto, conforme condição materna.</li><li>Ordenhar com frequência semelhante às mamadas de um recém-nascido.</li><li>Realizar contato pele a pele e Método Canguru quando liberado.</li><li>Registrar volumes sem transformar a ordenha em fonte de culpa.</li><li>Receber apoio para transição de sonda/copo para o peito, conforme maturidade.</li></ul>
<h2>Licença-maternidade em internação prolongada</h2>
<p>A Lei nº 15.222/2025 passou a permitir, em determinadas internações relacionadas ao parto que ultrapassem duas semanas, extensão da licença-maternidade por até 120 dias após a alta da mãe e do recém-nascido, descontado o período anterior ao parto, conforme requisitos legais.</p>', 'published', now(), 'manual'
from sec_9;

