insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Introdução alimentar e continuidade', '{"blocks":[{"type":"heading","level":2,"text":"Quando começar"},{"type":"paragraph","text":"A alimentação complementar deve começar por volta de seis meses completos, quando a criança apresenta prontidão e necessidade nutricional. O leite materno continua importante e pode ser oferecido antes ou depois das refeições conforme rotina e preferência."},{"type":"list","items":["Oferecer comida de verdade, variada e adequada à cultura da família.","Evoluir consistência; evitar liquidificar ou peneirar rotineiramente.","Oferecer água em copo a partir da introdução alimentar.","Evitar açúcar e ultraprocessados nos primeiros anos.","Respeitar sinais de fome e saciedade; não forçar.","Manter amamentação até dois anos ou mais."]}],"faqItems":[]}'::jsonb, '<h2>Quando começar</h2>
<p>A alimentação complementar deve começar por volta de seis meses completos, quando a criança apresenta prontidão e necessidade nutricional. O leite materno continua importante e pode ser oferecido antes ou depois das refeições conforme rotina e preferência.</p>
<ul><li>Oferecer comida de verdade, variada e adequada à cultura da família.</li><li>Evoluir consistência; evitar liquidificar ou peneirar rotineiramente.</li><li>Oferecer água em copo a partir da introdução alimentar.</li><li>Evitar açúcar e ultraprocessados nos primeiros anos.</li><li>Respeitar sinais de fome e saciedade; não forçar.</li><li>Manter amamentação até dois anos ou mais.</li></ul>', 'published', now(), 'manual'
from sec_10;

with sec_11 as (
  insert into sections (slug, order_index, icon, content_kind)
