insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Retorno ao trabalho e desmame', '{"blocks":[{"type":"heading","level":2,"text":"Planejar antes do retorno"},{"type":"list","items":["Converse com a rede de apoio e o local de trabalho.","Inicie treino de ordenha algumas semanas antes, sem formar estoque excessivo.","Teste recipientes e forma de oferta com outro cuidador.","Amamente antes de sair e ao reencontrar o bebê.","No trabalho, ordenhe em intervalos compatíveis com seu conforto e a idade do bebê.","Transporte em bolsa térmica adequada e armazene corretamente."]},{"type":"heading","level":2,"text":"Desmame"},{"type":"paragraph","text":"O desmame pode ser natural, gradual ou necessário por circunstâncias da família. Deve ser conduzido sem culpa e, quando possível, de forma progressiva para reduzir sofrimento e risco de ingurgitamento. Retire uma mamada de cada vez, substitua por vínculo e alimento adequado à idade e observe as reações da criança e das mamas."},{"type":"table","columns":["Situação","Conduta inicial"],"rows":[["Bebê mama muito","Observar sinais de fome, pega e deglutição; mamadas agrupadas podem ser normais."],["Pouco ganho de peso","Avaliação clínica completa, mamada observada, plano de aumento da transferência e reavaliação precoce."],["Retorno ao trabalho","Planejar ordenhas regulares e armazenamento."],["Relactação","Estimulação frequente, contato pele a pele, oferta ao peito e acompanhamento especializado."]]}],"faqItems":[]}'::jsonb, '<h2>Planejar antes do retorno</h2>
<ul><li>Converse com a rede de apoio e o local de trabalho.</li><li>Inicie treino de ordenha algumas semanas antes, sem formar estoque excessivo.</li><li>Teste recipientes e forma de oferta com outro cuidador.</li><li>Amamente antes de sair e ao reencontrar o bebê.</li><li>No trabalho, ordenhe em intervalos compatíveis com seu conforto e a idade do bebê.</li><li>Transporte em bolsa térmica adequada e armazene corretamente.</li></ul>
<h2>Desmame</h2>
<p>O desmame pode ser natural, gradual ou necessário por circunstâncias da família. Deve ser conduzido sem culpa e, quando possível, de forma progressiva para reduzir sofrimento e risco de ingurgitamento. Retire uma mamada de cada vez, substitua por vínculo e alimento adequado à idade e observe as reações da criança e das mamas.</p>
<table><thead><tr><th>Situação</th><th>Conduta inicial</th></tr></thead><tbody><tr><td>Bebê mama muito</td><td>Observar sinais de fome, pega e deglutição; mamadas agrupadas podem ser normais.</td></tr><tr><td>Pouco ganho de peso</td><td>Avaliação clínica completa, mamada observada, plano de aumento da transferência e reavaliação precoce.</td></tr><tr><td>Retorno ao trabalho</td><td>Planejar ordenhas regulares e armazenamento.</td></tr><tr><td>Relactação</td><td>Estimulação frequente, contato pele a pele, oferta ao peito e acompanhamento especializado.</td></tr></tbody></table>', 'published', now(), 'manual'
from sec_11;

