)
insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Mitos e verdades', '{"blocks":[{"type":"table","columns":["Afirmação","Esclarecimento"],"rows":[["“Meu leite é fraco.”","Mito. A aparência varia e leite mais claro não é fraco. Avalie ingestão por deglutição, fraldas, peso e estado clínico."],["“Peito pequeno produz pouco leite.”","Mito. O tamanho está mais relacionado à gordura que à capacidade de produção."],["“Bebê que mama toda hora não está satisfeito.”","Nem sempre. Mamadas frequentes e agrupadas podem ser normais, especialmente em surtos de crescimento."],["“Preciso lavar o mamilo antes de cada mamada.”","Mito. Higiene habitual no banho é suficiente; lavagem excessiva resseca e machuca."],["“Fissura precisa tomar sol.”","Não é recomendação de primeira linha. Corrigir pega e causa é essencial."],["“Mastite obriga parar de amamentar.”","Geralmente falso. Na maioria dos casos, manter a amamentação é seguro; avaliação clínica orienta exceções."],["“Cerveja preta aumenta leite.”","Mito e prática não recomendada. Álcool passa para o leite e pode prejudicar."],["“Depois de seis meses o leite vira água.”","Mito. Continua oferecendo energia, nutrientes e proteção imunológica."],["“Quem usa silicone não consegue amamentar.”","Nem sempre. Muitas mulheres amamentam; cirurgia, técnica e sensibilidade podem influenciar."],["“Chupeta não interfere.”","Pode interferir na frequência de sucção e no estabelecimento em alguns casos; deve ser discutida individualmente."],["“Fórmula faz o bebê dormir melhor.”","Não deve ser usada como estratégia de sono. O sono infantil depende de muitos fatores e fórmula tem indicações específicas."],["“Se fiquei nervosa, meu leite secou.”","Estresse pode dificultar temporariamente a ejeção, mas não costuma “secar” de repente. Apoio e estímulo ajudam."],["“É preciso alternar as mamas a cada dez minutos.”","Mito. O bebê pode terminar uma mama e depois receber a outra; o importante é transferência efetiva."],["“Amamentar em público é inadequado.”","Mito. Amamentar é uma necessidade da criança e deve ser respeitado."],["“Quem volta ao trabalho precisa desmamar.”","Mito. Ordenha, armazenamento, intervalos legais e apoio podem manter a amamentação."]]}],"faqItems":[]}'::jsonb, '<table><thead><tr><th>Afirmação</th><th>Esclarecimento</th></tr></thead><tbody><tr><td>“Meu leite é fraco.”</td><td>Mito. A aparência varia e leite mais claro não é fraco. Avalie ingestão por deglutição, fraldas, peso e estado clínico.</td></tr><tr><td>“Peito pequeno produz pouco leite.”</td><td>Mito. O tamanho está mais relacionado à gordura que à capacidade de produção.</td></tr><tr><td>“Bebê que mama toda hora não está satisfeito.”</td><td>Nem sempre. Mamadas frequentes e agrupadas podem ser normais, especialmente em surtos de crescimento.</td></tr><tr><td>“Preciso lavar o mamilo antes de cada mamada.”</td><td>Mito. Higiene habitual no banho é suficiente; lavagem excessiva resseca e machuca.</td></tr><tr><td>“Fissura precisa tomar sol.”</td><td>Não é recomendação de primeira linha. Corrigir pega e causa é essencial.</td></tr><tr><td>“Mastite obriga parar de amamentar.”</td><td>Geralmente falso. Na maioria dos casos, manter a amamentação é seguro; avaliação clínica orienta exceções.</td></tr><tr><td>“Cerveja preta aumenta leite.”</td><td>Mito e prática não recomendada. Álcool passa para o leite e pode prejudicar.</td></tr><tr><td>“Depois de seis meses o leite vira água.”</td><td>Mito. Continua oferecendo energia, nutrientes e proteção imunológica.</td></tr><tr><td>“Quem usa silicone não consegue amamentar.”</td><td>Nem sempre. Muitas mulheres amamentam; cirurgia, técnica e sensibilidade podem influenciar.</td></tr><tr><td>“Chupeta não interfere.”</td><td>Pode interferir na frequência de sucção e no estabelecimento em alguns casos; deve ser discutida individualmente.</td></tr><tr><td>“Fórmula faz o bebê dormir melhor.”</td><td>Não deve ser usada como estratégia de sono. O sono infantil depende de muitos fatores e fórmula tem indicações específicas.</td></tr><tr><td>“Se fiquei nervosa, meu leite secou.”</td><td>Estresse pode dificultar temporariamente a ejeção, mas não costuma “secar” de repente. Apoio e estímulo ajudam.</td></tr><tr><td>“É preciso alternar as mamas a cada dez minutos.”</td><td>Mito. O bebê pode terminar uma mama e depois receber a outra; o importante é transferência efetiva.</td></tr><tr><td>“Amamentar em público é inadequado.”</td><td>Mito. Amamentar é uma necessidade da criança e deve ser respeitado.</td></tr><tr><td>“Quem volta ao trabalho precisa desmamar.”</td><td>Mito. Ordenha, armazenamento, intervalos legais e apoio podem manter a amamentação.</td></tr></tbody></table>', 'published', now(), 'manual'
from sec_12;

