insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Direitos e legislação brasileira', '{"blocks":[{"type":"heading","level":2,"text":"Principais garantias"},{"type":"heading","level":3,"text":"Amamentação em espaço público"},{"type":"paragraph","text":"A mulher não precisa se esconder para alimentar o bebê. Estados e municípios podem ter normas específicas contra constrangimento. Mesmo na ausência de lei local específica, impedir ou humilhar uma mulher por amamentar pode violar dignidade, proteção à maternidade e direitos da criança."},{"type":"heading","level":3,"text":"Salas de apoio"},{"type":"paragraph","text":"São espaços privados, limpos e seguros em empresas ou instituições, destinados à ordenha e conservação do leite durante a jornada. Não são locais para isolar a mulher nem substituir o direito aos intervalos."},{"type":"table","columns":["Norma","Proteção relacionada"],"rows":[["Constituição Federal e CLT","Proteção à maternidade, licença-maternidade e estabilidade, conforme vínculo e requisitos."],["CLT, art. 396","Dois descansos especiais de meia hora durante a jornada para amamentar, até a criança completar seis meses; período pode ser ampliado quando a saúde exigir. Horários devem ser definidos em acordo individual."],["Lei nº 11.770/2008","Programa Empresa Cidadã: possibilidade de prorrogação da licença-maternidade para 180 dias em empresas aderentes e regras aplicáveis ao serviço público."],["Lei nº 11.265/2006 e Decreto nº 9.579/2018","NBCAL: regula promoção comercial de fórmulas, leites, alimentos infantis, mamadeiras, bicos e chupetas."],["Lei nº 13.435/2017","Institui agosto como Mês do Aleitamento Materno - Agosto Dourado."],["Lei nº 13.872/2019","Garante amamentação durante concursos públicos federais para filhos de até seis meses, com regras de solicitação e compensação do tempo."],["Lei nº 14.683/2023","Institui o Selo Empresa Amiga da Amamentação."],["Lei nº 15.222/2025","Amplia proteção da licença e do salário-maternidade em internações prolongadas relacionadas ao parto."],["Resolução Cofen nº 741/2024","Regulamenta a assistência de Enfermagem em Bancos e Postos de Coleta de Leite Humano."],["Resolução Cofen nº 736/2024","Dispõe sobre a implementação do Processo de Enfermagem em contextos de cuidado."]]}],"faqItems":[]}'::jsonb, '<h2>Principais garantias</h2>
<h3>Amamentação em espaço público</h3>
<p>A mulher não precisa se esconder para alimentar o bebê. Estados e municípios podem ter normas específicas contra constrangimento. Mesmo na ausência de lei local específica, impedir ou humilhar uma mulher por amamentar pode violar dignidade, proteção à maternidade e direitos da criança.</p>
<h3>Salas de apoio</h3>
<p>São espaços privados, limpos e seguros em empresas ou instituições, destinados à ordenha e conservação do leite durante a jornada. Não são locais para isolar a mulher nem substituir o direito aos intervalos.</p>
<table><thead><tr><th>Norma</th><th>Proteção relacionada</th></tr></thead><tbody><tr><td>Constituição Federal e CLT</td><td>Proteção à maternidade, licença-maternidade e estabilidade, conforme vínculo e requisitos.</td></tr><tr><td>CLT, art. 396</td><td>Dois descansos especiais de meia hora durante a jornada para amamentar, até a criança completar seis meses; período pode ser ampliado quando a saúde exigir. Horários devem ser definidos em acordo individual.</td></tr><tr><td>Lei nº 11.770/2008</td><td>Programa Empresa Cidadã: possibilidade de prorrogação da licença-maternidade para 180 dias em empresas aderentes e regras aplicáveis ao serviço público.</td></tr><tr><td>Lei nº 11.265/2006 e Decreto nº 9.579/2018</td><td>NBCAL: regula promoção comercial de fórmulas, leites, alimentos infantis, mamadeiras, bicos e chupetas.</td></tr><tr><td>Lei nº 13.435/2017</td><td>Institui agosto como Mês do Aleitamento Materno - Agosto Dourado.</td></tr><tr><td>Lei nº 13.872/2019</td><td>Garante amamentação durante concursos públicos federais para filhos de até seis meses, com regras de solicitação e compensação do tempo.</td></tr><tr><td>Lei nº 14.683/2023</td><td>Institui o Selo Empresa Amiga da Amamentação.</td></tr><tr><td>Lei nº 15.222/2025</td><td>Amplia proteção da licença e do salário-maternidade em internações prolongadas relacionadas ao parto.</td></tr><tr><td>Resolução Cofen nº 741/2024</td><td>Regulamenta a assistência de Enfermagem em Bancos e Postos de Coleta de Leite Humano.</td></tr><tr><td>Resolução Cofen nº 736/2024</td><td>Dispõe sobre a implementação do Processo de Enfermagem em contextos de cuidado.</td></tr></tbody></table>', 'published', now(), 'manual'
from sec_13;

