insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Atuação da Enfermagem e da Atenção Primária', '{"blocks":[{"type":"heading","level":2,"text":"Consulta de Enfermagem"},{"type":"paragraph","text":"A consulta deve seguir o Processo de Enfermagem: avaliação, diagnóstico de enfermagem, planejamento, implementação e evolução. O registro precisa ser claro, datado, individualizado e incluir orientações, resposta da mulher e do bebê e sinais de alerta."},{"type":"heading","level":3,"text":"Roteiro de avaliação"},{"type":"table","columns":["Domínio","O que avaliar"],"rows":[["História","Parto, idade gestacional, peso, internações, doenças, medicamentos, cirurgias mamárias, experiência anterior e objetivo da família."],["Mamada","Posição, pega, ritmo, deglutição, duração espontânea, dor, forma do mamilo após mamada."],["Bebê","Estado geral, hidratação, icterícia, boca, tônus, sucção, fraldas, fezes e curva de peso."],["Mamas","Formato, edema, trauma, dor, hiperemia, massa, secreções e sinais infecciosos."],["Contexto","Rede de apoio, saúde mental, sono, alimentação, trabalho, violência, barreiras culturais e linguísticas."]]},{"type":"heading","level":3,"text":"Condutas possíveis"},{"type":"list","items":["Aconselhamento e demonstração prática.","Correção de pega e posição.","Ordenha manual e plano de estímulo.","Manejo de ingurgitamento e trauma.","Monitoramento de peso e hidratação.","Encaminhamento médico, odontológico, fonoaudiológico, nutricional, psicológico ou ao Banco de Leite conforme necessidade.","Plano compartilhado de suplementação quando indicada.","Visita domiciliar e reavaliação precoce."]},{"type":"callout","tone":"warning","title":"Limite profissional","text":"Protocolos institucionais, legislação do exercício profissional e avaliação clínica devem orientar prescrições e procedimentos. Parecer técnico do Cofen de 2025 apontou que um material do Coren-PR sobre manejo ainda não atendia aos requisitos para ser reconhecido como protocolo nacional; portanto, não deve ser apresentado como protocolo homologado."}],"faqItems":[]}'::jsonb, '<h2>Consulta de Enfermagem</h2>
<p>A consulta deve seguir o Processo de Enfermagem: avaliação, diagnóstico de enfermagem, planejamento, implementação e evolução. O registro precisa ser claro, datado, individualizado e incluir orientações, resposta da mulher e do bebê e sinais de alerta.</p>
<h3>Roteiro de avaliação</h3>
<table><thead><tr><th>Domínio</th><th>O que avaliar</th></tr></thead><tbody><tr><td>História</td><td>Parto, idade gestacional, peso, internações, doenças, medicamentos, cirurgias mamárias, experiência anterior e objetivo da família.</td></tr><tr><td>Mamada</td><td>Posição, pega, ritmo, deglutição, duração espontânea, dor, forma do mamilo após mamada.</td></tr><tr><td>Bebê</td><td>Estado geral, hidratação, icterícia, boca, tônus, sucção, fraldas, fezes e curva de peso.</td></tr><tr><td>Mamas</td><td>Formato, edema, trauma, dor, hiperemia, massa, secreções e sinais infecciosos.</td></tr><tr><td>Contexto</td><td>Rede de apoio, saúde mental, sono, alimentação, trabalho, violência, barreiras culturais e linguísticas.</td></tr></tbody></table>
<h3>Condutas possíveis</h3>
<ul><li>Aconselhamento e demonstração prática.</li><li>Correção de pega e posição.</li><li>Ordenha manual e plano de estímulo.</li><li>Manejo de ingurgitamento e trauma.</li><li>Monitoramento de peso e hidratação.</li><li>Encaminhamento médico, odontológico, fonoaudiológico, nutricional, psicológico ou ao Banco de Leite conforme necessidade.</li><li>Plano compartilhado de suplementação quando indicada.</li><li>Visita domiciliar e reavaliação precoce.</li></ul>
<div class="callout callout-warning"><strong>Limite profissional</strong><p>Protocolos institucionais, legislação do exercício profissional e avaliação clínica devem orientar prescrições e procedimentos. Parecer técnico do Cofen de 2025 apontou que um material do Coren-PR sobre manejo ainda não atendia aos requisitos para ser reconhecido como protocolo nacional; portanto, não deve ser apresentado como protocolo homologado.</p></div>', 'published', now(), 'manual'
from sec_14;

