insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Foz do Iguaçu e região de fronteira', '{"blocks":[{"type":"heading","level":2,"text":"Atenção Primária como porta de entrada"},{"type":"paragraph","text":"Em Foz do Iguaçu, gestantes, puérperas e crianças devem buscar a Unidade Básica de Saúde de referência para pré-natal, consulta puerperal, puericultura, avaliação de peso, orientação de pega, vacinação e encaminhamentos. Contatos, horários e unidades de referência podem mudar; confirme nos canais oficiais da Secretaria Municipal da Saúde."},{"type":"heading","level":3,"text":"Particularidades da tríplice fronteira"},{"type":"list","items":["Circulação entre Brasil, Paraguai e Argentina, com possíveis dificuldades de continuidade do cuidado.","Diversidade linguística e cultural, incluindo famílias falantes de espanhol, guarani, árabe e outras línguas.","Diferenças de documentos, cobertura e local de nascimento.","Crenças familiares variadas sobre colostro, chás, horários, exposição do corpo e papel dos avós.","Necessidade de comunicação simples, intérprete quando possível e respeito às escolhas sem abrir mão da segurança."]},{"type":"heading","level":3,"text":"Como realizar aconselhamento intercultural"},{"type":"list","items":["Pergunte o que a família já sabe e acredita.","Identifique quem participa das decisões.","Explique o motivo de cada recomendação, sem ridicularizar crenças.","Negocie alternativas seguras.","Entregue orientação escrita no idioma compreendido.","Combine onde e quando será a reavaliação."]},{"type":"heading","level":3,"text":"Projeto de Lei Municipal nº 318/2025"},{"type":"paragraph","text":"O projeto propunha diretrizes para incentivo ao aleitamento materno, possível Passe Livre para lactantes e doadoras, salas de apoio, campanhas educativas e parcerias. Entretanto, a tramitação oficial registra que a proposição foi retirada pela autora e arquivada em fevereiro de 2026. Portanto, essas medidas não devem ser divulgadas como lei municipal vigente."},{"type":"callout","tone":"info","title":"Situação jurídica correta","text":"Projeto de lei não é lei. O texto pode inspirar políticas públicas, mas não cria direito exigível enquanto não for aprovado, sancionado e publicado."},{"type":"heading","level":3,"text":"Iniciativas legislativas posteriores"},{"type":"paragraph","text":"Em 2026 foi apresentada proposta municipal para exigir que creches públicas e privadas disponibilizem estrutura adequada para recepção e armazenamento de leite materno. A existência de proposta não significa vigência; a situação deve ser consultada no sistema legislativo municipal antes de qualquer divulgação."},{"type":"heading","level":3,"text":"Fluxo sugerido para a UBS"},{"type":"list","items":["Acolher sem julgamento e identificar urgência.","Observar mamada sempre que possível.","Avaliar mãe e bebê, incluindo peso e hidratação.","Realizar manejo inicial e registrar.","Definir retorno em 24-72 horas conforme risco.","Encaminhar para maternidade, pediatria, banco de leite ou urgência quando necessário.","Garantir continuidade para famílias que atravessam a fronteira."]}],"faqItems":[]}'::jsonb, '<h2>Atenção Primária como porta de entrada</h2>
<p>Em Foz do Iguaçu, gestantes, puérperas e crianças devem buscar a Unidade Básica de Saúde de referência para pré-natal, consulta puerperal, puericultura, avaliação de peso, orientação de pega, vacinação e encaminhamentos. Contatos, horários e unidades de referência podem mudar; confirme nos canais oficiais da Secretaria Municipal da Saúde.</p>
<h3>Particularidades da tríplice fronteira</h3>
<ul><li>Circulação entre Brasil, Paraguai e Argentina, com possíveis dificuldades de continuidade do cuidado.</li><li>Diversidade linguística e cultural, incluindo famílias falantes de espanhol, guarani, árabe e outras línguas.</li><li>Diferenças de documentos, cobertura e local de nascimento.</li><li>Crenças familiares variadas sobre colostro, chás, horários, exposição do corpo e papel dos avós.</li><li>Necessidade de comunicação simples, intérprete quando possível e respeito às escolhas sem abrir mão da segurança.</li></ul>
<h3>Como realizar aconselhamento intercultural</h3>
<ul><li>Pergunte o que a família já sabe e acredita.</li><li>Identifique quem participa das decisões.</li><li>Explique o motivo de cada recomendação, sem ridicularizar crenças.</li><li>Negocie alternativas seguras.</li><li>Entregue orientação escrita no idioma compreendido.</li><li>Combine onde e quando será a reavaliação.</li></ul>
<h3>Projeto de Lei Municipal nº 318/2025</h3>
<p>O projeto propunha diretrizes para incentivo ao aleitamento materno, possível Passe Livre para lactantes e doadoras, salas de apoio, campanhas educativas e parcerias. Entretanto, a tramitação oficial registra que a proposição foi retirada pela autora e arquivada em fevereiro de 2026. Portanto, essas medidas não devem ser divulgadas como lei municipal vigente.</p>
<div class="callout callout-info"><strong>Situação jurídica correta</strong><p>Projeto de lei não é lei. O texto pode inspirar políticas públicas, mas não cria direito exigível enquanto não for aprovado, sancionado e publicado.</p></div>
<h3>Iniciativas legislativas posteriores</h3>
<p>Em 2026 foi apresentada proposta municipal para exigir que creches públicas e privadas disponibilizem estrutura adequada para recepção e armazenamento de leite materno. A existência de proposta não significa vigência; a situação deve ser consultada no sistema legislativo municipal antes de qualquer divulgação.</p>
<h3>Fluxo sugerido para a UBS</h3>
<ul><li>Acolher sem julgamento e identificar urgência.</li><li>Observar mamada sempre que possível.</li><li>Avaliar mãe e bebê, incluindo peso e hidratação.</li><li>Realizar manejo inicial e registrar.</li><li>Definir retorno em 24-72 horas conforme risco.</li><li>Encaminhar para maternidade, pediatria, banco de leite ou urgência quando necessário.</li><li>Garantir continuidade para famílias que atravessam a fronteira.</li></ul>', 'published', now(), 'manual'
from sec_15;

