insert into section_translations (section_id, language_code, title, body, body_html_cache, status, translated_at, translation_engine)
select id, 'pt', 'Perguntas frequentes', '{"blocks":[],"faqItems":[{"question":"Quanto tempo deve durar a mamada?","answer":"Não há duração fixa. Observe sucção e deglutição; deixe o bebê terminar espontaneamente."},{"question":"Preciso oferecer as duas mamas?","answer":"Ofereça a primeira até o bebê soltar ou reduzir a sucção; depois ofereça a segunda. Na próxima mamada, pode começar pela última menos esvaziada."},{"question":"Posso amamentar deitada?","answer":"Pode, desde que mãe e bebê estejam bem posicionados e o ambiente seja seguro. Cuidado com adormecer em sofás ou poltronas."},{"question":"Posso fazer atividade física?","answer":"Em geral, sim, após liberação e recuperação. Hidrate-se e use suporte confortável."},{"question":"Posso pintar o cabelo?","answer":"Muitos produtos têm baixa absorção, mas recomenda-se ventilação, evitar contato do bebê e seguir orientações do fabricante e do profissional de saúde."},{"question":"Posso fazer exame com contraste?","answer":"Muitos contrastes são compatíveis, mas confirme o tipo específico; não suspenda automaticamente."},{"question":"Meu bebê dormiu muitas horas. Acordo?","answer":"Depende da idade, peso e condição clínica. Recém-nascidos com risco precisam de orientação individual."},{"question":"Posso usar concha ou bico de silicone?","answer":"Não devem ser rotina. Podem ajudar em situações específicas, com acompanhamento, pois podem piorar trauma ou reduzir transferência."},{"question":"Como saber se a bomba está correta?","answer":"Não deve doer, puxar muita aréola nem machucar. Ajuste funil e sucção."},{"question":"Posso doar leite?","answer":"Mulheres saudáveis, com produção excedente, podem procurar um Banco de Leite para triagem e orientação."},{"question":"É possível voltar a produzir leite depois de parar?","answer":"Sim, relactação é possível em muitos casos, mas exige estímulo frequente e acompanhamento."},{"question":"A fórmula é proibida?","answer":"Não. É um alimento indicado em situações específicas. Deve ser preparada com segurança e não promovida de forma comercial inadequada."},{"question":"O pai ou acompanhante pode ajudar?","answer":"Muito: proteger o descanso, cuidar da casa, levar água e comida, apoiar posições, observar sinais e evitar palpites que gerem culpa."},{"question":"Avós podem participar?","answer":"Sim. São parte importante da rede. Informações atualizadas ajudam a substituir práticas antigas, como oferecer chá, por apoio seguro."},{"question":"Quando procurar um Banco de Leite?","answer":"Dor, dificuldade de pega, baixa produção, excesso de leite, necessidade de ordenha, prematuridade ou interesse em doar são motivos comuns."}]}'::jsonb, '', 'published', now(), 'manual'
from sec_17;

